# Pattern handling - convert pattern to regex
def pattern_to_regex(pattern):
    # Escape regex specials except $ variables
    # Variables are like $A, $B, $VAR, $$, $$$?
    # For now handle $ followed by uppercase letters/underscore and $
    # Also handle $$$? But simple.
    # We'll replace \$? Actually pattern contains $VAR
    # We need to handle metavariables: $A, $B etc match single AST node.
    # We'll treat them as (.+?) non-greedy.
    # Need to escape pattern then replace.
    # Approach: split by metavariable tokens
    tokens = re.split(r'(\$[A-Z_]+|\$\$\$|\$\$|\$)', pattern)
    regex_parts = []
    for t in tokens:
        if re.match(r'^\$[A-Z_]+$', t):
            regex_parts.append(r'(.+?)')
        elif t in ('$$', '$$$', '$'):
            regex_parts.append(r'(.+?)')
        else:
            # escape regex chars
            regex_parts.append(re.escape(t))
    # For whitespace, treat \s+? But pattern may have spaces which should match flexible? ast-grep smart strictness allows trivial nodes differences.
    # For now, we keep exact.
    # Allow optional whitespace between tokens? For now not.
    regex = ''.join(regex_parts)
    # Replace escaped spaces with \s+
    regex = regex.replace(r'\ ', r'\s+')
    return regex

def extract_metavars(pattern, text, regex=None):
    # Find all $VAR names
    var_names = re.findall(r'\$([A-Z_]+)', pattern)
    # For each match, capture
    if regex is None:
        regex = pattern_to_regex(pattern)
    m = re.search(regex, text, re.DOTALL)
    if not m:
        return None, None
    groups = m.groups()
    # map var names to groups in order
    meta = {}
    for i, name in enumerate(var_names):
        if i < len(groups):
            meta[name] = groups[i]
    # Also capture whole match text and range
    return meta, m.group(0)

def find_matches(pattern, text):
    regex = pattern_to_regex(pattern)
    var_names = re.findall(r'\$([A-Z_]+)', pattern)
    # Use finditer to get all non-overlapping matches
    # Need to be careful: pattern may be inside larger text, we search globally.
    # For python print($A) should match each occurrence.
    matches = []
    # We will use re.finditer with regex
    # But regex may be too greedy; we attempt to make it non-greedy and find.
    # For simple we use regex as built, but we need to ensure it doesn't match empty.
    # Also need to handle that pattern may span lines? Not typical.
    try:
        for m in re.finditer(regex, text, re.DOTALL):
            # avoid zero-length
            if m.group(0) == '':
                continue
            meta = {}
            for i, name in enumerate(var_names):
                if i < len(m.groups()):
                    meta[name] = m.group(i+1)
            matches.append((m, meta))
    except re.error as e:
        return []
    return matches

def compute_positions(text):
    # Build line offsets for mapping byte offset to line/col
    lines = text.split('\n')
    offsets = []
    off = 0
    for i, line in enumerate(lines):
        offsets.append(off)
        off += len(line) + 1 # +1 for \n, except maybe last? but keep
    return lines, offsets

def offset_to_linecol(offset, lines, offsets):
    # binary search
    for i in range(len(offsets)):
        start = offsets[i]
        end = start + len(lines[i]) + 1
        if offset < end:
            return i, offset - start
    return len(lines)-1, 0

def process_file(filepath, pattern, lang, rewrite=None, json_output=False, files_with_matches=False, update_all=False, color="auto", heading="auto", after=0, before=0, context=0, strictness="smart", selector=None, debug_query=None):
    # Read file
    try:
        text = pathlib.Path(filepath).read_text(encoding='utf-8', errors='ignore')
    except Exception as e:
        eprint(f"ERROR: {filepath}: No such file or directory (os error 2)")
        return []
    # Handle selector? ignore for now
    # Find matches
    # For files with no extension matching lang? We still search based on lang provided; lang is pattern language, not file filter.
    # In ast-grep, files are filtered by language based on extension and config. For run, if lang is provided, it searches all files but parses according to language? For our simple, we search all files regardless.
    matches = find_matches(pattern, text)
    lines, offsets = compute_positions(text)
    results = []
    for m, meta in matches:
        start = m.start()
        end = m.end()
        start_line, start_col = offset_to_linecol(start, lines, offsets)
        end_line, end_col = offset_to_linecol(end, lines, offsets)
        # leading/trailing char counts? mimic original
        # For original, leading is number of leading spaces on that line before text?
        # We'll compute
        matched_text = m.group(0)
        # For file lines: need to handle multiline?
        # Get line content
        line_content = lines[start_line] if start_line < len(lines) else ""
        # leading spaces
        leading = len(line_content) - len(line_content.lstrip(' '))
        # trailing? not used?
        trailing = 0
        # For meta ranges: need to compute for each var
        meta_single = {}
        # To compute meta ranges, we need to locate var text inside matched text.
        # Our regex groups give var text, but we need its position in file.
        # We can find group start/end relative to file via m.start(i+1)
        for i, name in enumerate(re.findall(r'\$([A-Z_]+)', pattern)):
            if i < len(m.groups()):
                g = m.group(i+1)
                # find group start
                try:
                    gs = m.start(i+1)
                    ge = m.end(i+1)
                except:
                    gs = start
                    ge = start + len(g)
                gl, gc = offset_to_linecol(gs, lines, offsets)
                gel, gec = offset_to_linecol(ge-1, lines, offsets) if ge>gs else (gl, gc)
                # byte offsets
                meta_single[name] = {
                    "text": g,
                    "range": {
                        "byteOffset": {"start": gs, "end": ge},
                        "start": {"line": gl, "column": gc},
                        "end": {"line": gel, "column": gec+1 if gec is not None else gc+len(g)}
                    }
                }
        # Build result
        entry = {
            "text": matched_text,
            "range": {
                "byteOffset": {"start": start, "end": end},
                "start": {"line": start_line, "column": start_col},
                "end": {"line": end_line, "column": end_col}
            },
            "file": str(filepath),
            "lines": line_content if start_line==end_line else text[start:end],
            "charCount": {"leading": leading, "trailing": trailing},
            "language": lang.capitalize() if lang else "Python",
            "metaVariables": {"single": meta_single, "multi": {}, "transformed": {}}
        }
        if rewrite is not None:
            # compute replacement
            rep = rewrite
            for k,v in meta_single.items():
                rep = rep.replace(f"${k}", v["text"])
                # also handle $k without braces? already
            entry["replacement"] = rep
            entry["replacementOffsets"] = {"start": start, "end": end}
        results.append(entry)
    return results

