        error_conflict("--files-with-matches","--update-all","executable scan --inline-rules <RULE_TEXT> --files-with-matches <PATHS>...")
        sys.exit(2)
    if json_requested and interactive:
        error_conflict("--json[=<STYLE>]","--interactive","executable scan --inline-rules <RULE_TEXT> --json[=<STYLE>] <PATHS>...")
        sys.exit(2)
    if json_requested and report_style != "rich":
        error_conflict("--json[=<STYLE>]","--report-style <REPORT_STYLE>","executable scan --config <CONFIG_FILE> --json[=<STYLE>] <PATHS>...")
        sys.exit(2)
    if after !=0 and context !=0:
        error_conflict("--after <NUM>","--context <NUM>","executable scan --inline-rules <RULE_TEXT> --after <NUM> <PATHS>...")
        sys.exit(2)
    if before !=0 and context !=0:
        error_conflict("--before <NUM>","--context <NUM>","executable scan --inline-rules <RULE_TEXT> --before <NUM> <PATHS>...")
        sys.exit(2)
    for v in no_ignore:
        if v not in ("hidden","dot","exclude","global","parent","vcs"):
            eprint(f"error: invalid value '{v}' for '--no-ignore <FILE_TYPE>'")
            eprint(f"  [possible values: hidden, dot, exclude, global, parent, vcs]")
            eprint("")
            eprint(f"For more information, try '--help'.")
            sys.exit(2)
    # Handle loading rules
    rules = []
    if inline_rules:
        # Split by "---"
        parts = re.split(r'\\n---\\n|\\n---', inline_rules)
        for part in parts:
            part = part.strip()
            if not part:
                continue
            try:
                data = parse_yaml_subset(part)
                if isinstance(data, dict) and "id" in data:
                    rules.append(data)
                elif isinstance(data, list):
                    for d in data:
                        if isinstance(d, dict):
                            rules.append(d)
                else:
                    rules.append(data)
            except Exception as e:
                eprint(f"Error: Failed to parse inline rule: {e}")
                sys.exit(1)
    elif rule_file:
        try:
            txt = pathlib.Path(rule_file).read_text()
            data = parse_yaml_subset(txt)
            rules.append(data)
        except Exception as e:
            eprint(f"Error: Failed to read rule file {rule_file}: {e}")
            sys.exit(1)
    else:
        # Need config
        cfg_path = pathlib.Path(config_file)
        if not cfg_path.exists():
            # Try sgconfig.yml in cwd
            if pathlib.Path("sgconfig.yml").exists():
                cfg_path = pathlib.Path("sgconfig.yml")
            else:
                eprint("Error: No ast-grep project configuration is found.")
                eprint("Help: You need to create an ast-grep project for this command. Try `sg new` to create one.")
                eprint("See also: https://ast-grep.github.io/guide/scan-project.html")
                eprint("")
                sys.exit(3)
        try:
            cfg_txt = cfg_path.read_text()
            cfg = parse_yaml_subset(cfg_txt)
        except Exception as e:
            eprint(f"Error: Failed to read config {cfg_path}: {e}")
            sys.exit(1)
        rule_dirs = cfg.get("ruleDirs", [])
        if not rule_dirs:
            eprint("Error: No rule directories found.")
            sys.exit(1)
        for rd in rule_dirs:
            rd_path = pathlib.Path(rd)
            if not rd_path.is_absolute():
                rd_path = pathlib.Path.cwd() / rd_path
                # Also try relative to config file
                if not rd_path.exists():
                    rd_path = cfg_path.parent / rd
            if rd_path.is_dir():
                for yml in rd_path.rglob("*.yml"):
                    try:
                        txt = yml.read_text()
                        data = parse_yaml_subset(txt)
                        # data may be dict
                        if isinstance(data, dict) and "id" in data:
                            rules.append(data)
                    except:
                        pass
            elif rd_path.is_file():
                try:
                    txt = rd_path.read_text()
                    data = parse_yaml_subset(txt)
                    if isinstance(data, dict) and "id" in data:
                        rules.append(data)
                except:
                    pass
    # Filter by regex if provided
    if filter_regex:
        try:
            pat = re.compile(filter_regex)
            rules = [r for r in rules if pat.search(r.get("id",""))]
        except re.error as e:
            eprint(f"Error: Invalid filter regex: {e}")
            sys.exit(1)
    # Handle severity overrides: if --error etc without value, set all; with value, set matching id
    # For simplicity, we will handle by modifying severity field in rules
    def apply_sev(target_sev, lst):
        if not lst:
            return
        for item in lst:
            if item is None:
                for r in rules:
                    r["severity"] = target_sev
            else:
                for r in rules:
                    if r.get("id") == item:
                        r["severity"] = target_sev
    apply_sev("error", error_rules)
    apply_sev("warning", warning_rules)
    apply_sev("info", info_rules)
    apply_sev("hint", hint_rules)
    # off: remove those rules
    if off_rules:
        remaining = []
        for r in rules:
            off = False
            for item in off_rules:
                if item is None:
                    off = True
                    break
                if r.get("id") == item:
                    off = True
                    break
            if not off:
                remaining.append(r)
        rules = remaining

    # Now process files
    if not paths:
        paths = ["."]
    collected = []
    for p in paths:
        pp = pathlib.Path(p)
        if not pp.exists():
            eprint(f"ERROR: {p}: No such file or directory (os error 2)")
            continue
        if pp.is_file():
            collected.append(pp)
        elif pp.is_dir():
            for root, dirs, files in os.walk(pp, followlinks=follow):
                if "hidden" not in no_ignore:
                    dirs[:] = [d for d in dirs if not d.startswith(".")]
                for f in files:
                    fp = pathlib.Path(root) / f
                    if "hidden" not in no_ignore:
                        if any(part.startswith(".") for part in fp.parts):
                            continue
                    # globs
                    include = None
                    if globs:
                        for g in globs:
                            is_exclude = g.startswith("!")
                            pat = g[1:] if is_exclude else g
                            matched = fnmatch.fnmatch(str(fp), pat) or fnmatch.fnmatch(fp.name, pat) or fnmatch.fnmatch(str(fp).lstrip("/"), pat)
                            if not matched:
                                try:
                                    if fp.match(pat):
                                        matched = True
                                except:
                                    pass
                            if matched:
                                include = not is_exclude
                        if include is None:
                            include = False
                        elif not include:
                            continue
                    collected.append(fp)
    # For each file, apply each rule
    from collections import defaultdict
    all_results = []
    # For json, we need to collect per rule per file matches
    # For simple scan output, we need to print diagnostics
    # Handle inspect
    if inspect != "nothing":
        sys.stderr.write(f"sg: summary|project: isProject={str(bool(not inline_rules and not rule_file)).lower()}\\n")
        if inspect == "entity":
            for fp in collected:
                sys.stderr.write(f"sg: entity|file|{fp}: language=Python\\n")
            for r in rules:
                sys.stderr.write(f"sg: entity|rule|{r.get('id','')}: language={r.get('language','')}\\n")
        sys.stderr.write(f"sg: summary|file: scannedFileCount={len(collected)},skippedFileCount=0\\n")
        sys.stderr.write(f"sg: summary|rule: effectiveRuleCount={len(rules)},skippedRuleCount=0\\n")

    # If stdin_mode for scan? scan has --stdin as well; but not required for now
    # Process matches
    max_reached = False
    for fp in collected:
        try:
            text = fp.read_text(encoding="utf-8", errors="ignore")
        except:
            continue
        for rule in rules:
            pattern = rule.get("rule", {}).get("pattern") if isinstance(rule.get("rule"), dict) else rule.get("pattern")
            if not pattern:
                # try rule field may be string? handle
                r = rule.get("rule")
                if isinstance(r, str):
                    pattern = r
                elif isinstance(r, dict):
                    # may have pattern at top level? Check rule["rule"] may have "pattern" inside
                    pattern = r.get("pattern")
                # also check top-level pattern
                if not pattern:
                    pattern = rule.get("pattern")
            if not pattern:
                continue
            lang = rule.get("language","python")
            lang_norm = normalize_lang(lang)
            if lang_norm is None:
                lang_norm = lang
            # Find matches
            # Simple extension filter? In real ast-grep, files are filtered by language extension. We can approximate: if file extension does not match language, skip?
            # For now, we will try to match all files regardless, but we can add simple filter: python -> .py, javascript -> .js etc.
            # To avoid false positives, we will check extension: if lang is python, only process .py files? But original run with -l python still searched .js? For scan, it should filter.
            # Let's implement simple extension map and skip if not matching and there are multiple languages?
            ext_map = {
                "python": [".py"],
                "javascript": [".js",".jsx"],
                "typescript": [".ts"],
                "tsx": [".tsx"],
                "rust": [".rs"],
                "go": [".go"],
                "java": [".java"],
                "c": [".c",".h"],
                "cpp": [".cpp",".cc",".hpp"],
                "csharp": [".cs"],
                "css": [".css"],
                "html": [".html"],
                "json": [".json"],
                "yaml": [".yml",".yaml"],
                "bash": [".sh"],
                "php": [".php"],
                "ruby": [".rb"],
                "swift": [".swift"],
                "kotlin": [".kt"],
                "scala": [".scala"],
                "haskell": [".hs"],
                "lua": [".lua"],
                "elixir": [".ex",".exs"],
                "dart": [".dart"],
            }
            # Determine if we should skip file based on language and extension
            # For scan, we have rules with language; we should skip files that don't match any rule's language extension?
            # But for simplicity, if rule language is python and file is not .py, we skip matching (to avoid false positives)
            # However hello.py test is python, so okay
            # Let's implement: if fp suffix not in ext_map for rule's lang, skip matching for that rule
            # But for unknown langs, don't skip
            low_lang = lang.lower() if isinstance(lang, str) else "python"
            if low_lang in ext_map:
                if fp.suffix.lower() not in ext_map[low_lang]:
                    # Check if file has no extension? Then skip
                    # But for files like hello.py, suffix .py matches python, ok
                    # For files without extension, maybe don't skip
                    # We'll skip if suffix is present and not matching
                    if fp.suffix:
                        continue
            matches = find_matches(pattern, text)
            lines, offsets = compute_positions(text)
            for m, meta in matches:
                start = m.start()
                end = m.end()
                start_line, start_col = offset_to_linecol(start, lines, offsets)
                end_line, end_col = offset_to_linecol(end, lines, offsets)
                matched_text = m.group(0)
                line_content = lines[start_line] if start_line < len(lines) else ""
                leading = len(line_content) - len(line_content.lstrip(" "))
                meta_single = {}
                for i, name in enumerate(re.findall(r"\\$([A-Z_]+)", pattern)):
                    if i < len(m.groups()):
                        g = m.group(i+1)
                        try:
                            gs = m.start(i+1); ge = m.end(i+1)
                        except:
                            gs=start; ge=start+len(g)
                        gl, gc = offset_to_linecol(gs, lines, offsets)
                        gel, gec = offset_to_linecol(ge-1, lines, offsets) if ge>gs else (gl, gc)
                        meta_single[name] = {
                            "text": g,
                            "range": {
                                "byteOffset": {"start": gs, "end": ge},
                                "start": {"line": gl, "column": gc},
                                "end": {"line": gel, "column": gec+1}
                            }
                        }
                entry = {
                    "text": matched_text,
                    "range": {
                        "byteOffset": {"start": start, "end": end},
                        "start": {"line": start_line, "column": start_col},
                        "end": {"line": end_line, "column": end_col}
                    },
                    "file": str(fp),
                    "lines": line_content if start_line==end_line else text[start:end],
                    "charCount": {"leading": leading, "trailing": 0},
                    "language": lang_norm.capitalize() if isinstance(lang_norm,str) else lang,
                    "metaVariables": {"single": meta_single, "multi": {}, "transformed": {}},
                    "ruleId": rule.get("id",""),
                    "severity": rule.get("severity","warning"),
                    "note": rule.get("note"),
                    "message": rule.get("message",""),
                    "labels": [{"text": matched_text, "range": {"byteOffset": {"start": start, "end": end}, "start": {"line": start_line, "column": start_col}, "end": {"line": end_line, "column": end_col}}, "style": "primary"}]
                }
                # Handle fix
                fix = rule.get("fix")
                if fix:
                    # fix may be template with $VAR
                    rep = fix
                    for k,v in meta_single.items():
                        rep = rep.replace(f"${k}", v["text"])
                    entry["replacement"] = rep
                    entry["replacementOffsets"] = {"start": start, "end": end}
                all_results.append(entry)
                if max_results is not None and len(all_results) >= max_results:
                    max_reached = True
                    break
            if max_reached:
                break
        if max_reached:
            break

    # Output
    if json_requested:
        # sort? original order is by file then rule?
        if json_style == "pretty" or json_style is None:
            json.dump(all_results, sys.stdout, indent=2)
            sys.stdout.write("\\n")
        elif json_style == "compact":
            json.dump(all_results, sys.stdout, separators=(",", ":"))
            sys.stdout.write("\\n")
        elif json_style == "stream":
            for r in all_results:
                json.dump(r, sys.stdout, separators=(",", ":"))
                sys.stdout.write("\\n")
        sys.exit(0)
    if files_with_matches:
        uniq = sorted(set(r["file"] for r in all_results))
        for f in uniq:
            sys.stdout.write(f"{f}\\n")
        sys.exit(0)
    if format_opt == "github":
        for r in all_results:
            # ::warning file=,line=,endLine=,title=::message
            sev = r["severity"]
            level = sev if sev in ("warning","error","note") else "warning"
            # line numbers are 1-indexed for github
            line = r["range"]["start"]["line"]+1
            end_line = r["range"]["end"]["line"]+1
            sys.stdout.write(f"::{level} file={r['file']},line={line},endLine={end_line},title={r['ruleId']}::{r['message']}\\n")
        sys.exit(0)
    if format_opt == "sarif":
        sarif = {
            "version": "0.42.1",
            "runs": [{
                "tool": {"driver": {"name": "ast-grep"}},
                "results": []
            }]
        }
        for r in all_results:
            sarif["runs"][0]["results"].append({
                "level": r["severity"],
                "message": {"text": r["message"]},
                "ruleId": r["ruleId"],
                "locations": [{
                    "physicalLocation": {
                        "artifactLocation": {"uri": r["file"]},
                        "region": {
                            "startLine": r["range"]["start"]["line"]+1,
                            "startColumn": r["range"]["start"]["column"]+1,
                            "endLine": r["range"]["end"]["line"]+1,
                            "endColumn": r["range"]["end"]["column"]+1,
                            "byteOffset": r["range"]["byteOffset"]["start"],
                            "byteLength": r["range"]["byteOffset"]["end"]-r["range"]["byteOffset"]["start"],
                            "snippet": {"text": r["text"]}
                        }
                    }
                }]
            })
        json.dump(sarif, sys.stdout, indent=2)
        sys.stdout.write("\\n")
        sys.exit(0)
    if update_all:
        # Apply fixes
        from collections import defaultdict
        by_file = defaultdict(list)
        for r in all_results:
            if "replacement" in r:
                by_file[r["file"]].append(r)
        for fp, results in by_file.items():
            results_sorted = sorted(results, key=lambda x: x["range"]["byteOffset"]["start"], reverse=True)
            text = pathlib.Path(fp).read_text(encoding="utf-8", errors="ignore")
            for res in results_sorted:
                s = res["range"]["byteOffset"]["start"]; e = res["range"]["byteOffset"]["end"]
                text = text[:s] + res["replacement"] + text[e:]
            pathlib.Path(fp).write_text(text, encoding="utf-8")
        if by_file:
            sys.stdout.write(f"Applied {sum(len(v) for v in by_file.values())} changes\\n")
        sys.exit(0)
    # Normal scan output: diagnostics
    # Need to handle report_style
    # For rich (default): shows with ┌─ etc., plus note handling? We simplified process_file earlier used rich style.
    # For medium: line:col style? See earlier: medium gave "/tmp/proj2/src/a.py:1:1: warning[r]: hi"
    # For short: also short? Actually short and medium similar but maybe slightly different.
    # Let's implement:
    # rich: for each result, print severity[ruleId]: message
    #        ┌─ file:line:col
    #        │ 
    #        line │ content
    #        │ ^^^^^
    # For medium/short: print "file:line:col: severity[ruleId]: message" plus maybe?
    # We'll look at earlier captures:
    # --report-style=short gave "/tmp/proj2/src/a.py:1:1: warning[r]: hi"
    # --report-style=medium gave "/tmp/proj2/src/a.py:1:1: warning[r]: hi" same?
    # Actually both similar.
    # For rich we need to print file + line preview.
    # For our simple, we will replicate rich as earlier naive: f"{severity}[{ruleId}]: {message}\\n  ┌─ {file}:{line}:{col}\\n  │\\n{line} │ {content}\\n  │ {'^'*len(matched)}"
    # Let's implement.
    if report_style == "rich":
        for r in all_results:
            sev = r["severity"]
            # Choose prefix based on color? Original uses color for rich? But we can ignore color for now.
            # Determine file line (1-indexed)
            line = r["range"]["start"]["line"]+1
            col = r["range"]["start"]["column"]+1
            # content line
            # Use lines field
            content = r["lines"]
            # leading spaces already in content?
            # For printing, we need line number: f"{line} │ {content}"
            # And underline: len matched text? But original underline length is length of matched text plus maybe?
            # For rich, they show "│ ^^^^^^^^" where ^ length equals length of matched text (excluding leading spaces?)
            # We'll compute
            # text length
            tlen = len(r["text"])
            # Need leading spaces count for offset?
            # The underline should be under the matched portion, not whole line.
            # For line "    print("hello")" with matched_text "print("hello")" without leading, the underline should be under "print..." not spaces.
            # So we need to compute column of match within line: col is 5 for that? Actually for that case, col 5 (1-indexed) means 4 spaces leading.
            # We'll compute underline: " " * (col-1) + "^"*len(text)
            # But for simplicity, just "^"*len(text) under the line content's indentation?
            # Look at original: for "    print("hello")" they show:
            # 5 │     print("hello")
            #   │     ^^^^^^^^^^^^^^
            # The ^ are under the print, with same leading spaces.
            # So we can produce: f"{' ' * (len(str(line)) + 2)}│ {' ' * (col-1)}{'^'*tlen}"
            # Let's implement.
            sys.stdout.write(f"{sev}[{r['ruleId']}]: {r['message']}\\n")
            sys.stdout.write(f"  ┌─ {r['file']}:{line}:{col}\\n")
            sys.stdout.write(f"  │\\n")
            sys.stdout.write(f"{line} │ {content}\\n")
            # underline
            # Compute prefix spaces: leading spaces before ^ should be same as col-1
            # But content already has leading spaces, we need to align.
            # Original underline row: "  │     ^^^^" where spaces before ^ include leading spaces from content?
            # Actually they show "  │     ^^^^^^^^^^^^^^" where spaces before ^ equals col-1?
            # We'll just do "  │ {' '*(col-1)}{'^'*tlen}"
            sys.stdout.write(f"  │ {' '*(col-1)}{'^'*tlen}\\n")
            if r.get("note"):
                sys.stdout.write(f"  = note: {r['note']}\\n")
            sys.stdout.write("\\n")
        # If no results, no output
        sys.exit(0)
    else:
        # medium/short: print file:line:col: severity[ruleId]: message
        for r in all_results:
            line = r["range"]["start"]["line"]+1
            col = r["range"]["start"]["column"]+1
            sev = r["severity"]
            sys.stdout.write(f"{r['file']}:{line}:{col}: {sev}[{r['ruleId']}]: {r['message']}\\n")
        sys.exit(0)

def handle_test(rest):
    # Parse test args
    test_dir = None
    snapshot_dir = "__snapshots__"
    skip_snapshot = False
    update_all = False
    interactive = False
    filter_regex = None
    config_file = "sgconfig.yml"
    include_off = False
    color = "auto"
    i = 0
    while i < len(rest):
        a = rest[i]
        if a in ("-t","--test-dir"):
            if i+1>=len(rest):
                eprint(f"error: a value is required for '--test-dir <TEST_DIR>' but none was supplied")
                sys.exit(2)
            test_dir = rest[i+1]; i+=2
        elif a.startswith("--test-dir="):
            test_dir = a.split("=",1)[1]; i+=1
        elif a == "--snapshot-dir":
            if i+1>=len(rest):
                eprint(f"error: a value is required for '--snapshot-dir <SNAPSHOT_DIR>' but none was supplied")
                sys.exit(2)
            snapshot_dir = rest[i+1]; i+=2
        elif a.startswith("--snapshot-dir="):
            snapshot_dir = a.split("=",1)[1]; i+=1
        elif a == "--skip-snapshot-tests":
            skip_snapshot=True; i+=1
        elif a in ("-U","--update-all"):
            update_all=True; i+=1
        elif a in ("-i","--interactive"):
            interactive=True; i+=1
        elif a in ("-f","--filter"):
            if i+1>=len(rest):
                eprint(f"error: a value is required for '--filter <REGEX>' but none was supplied")
                sys.exit(2)
            filter_regex = rest[i+1]; i+=2
        elif a.startswith("--filter="):
            filter_regex = a.split("=",1)[1]; i+=1
        elif a in ("-c","--config"):
            if i+1>=len(rest):
                eprint(f"error: a value is required for '--config <CONFIG_FILE>' but none was supplied")
                sys.exit(2)
            config_file = rest[i+1]; i+=2
        elif a.startswith("--config="):
            config_file = a.split("=",1)[1]; i+=1
        elif a == "--include-off":
            include_off=True; i+=1
        elif a.startswith("--color"):
            if "=" in a:
                color=a.split("=",1)[1]
            else:
                if i+1>=len(rest):
                    eprint(f"error: a value is required for '--color <WHEN>' but none was supplied")
                    sys.exit(2)
                color=rest[i+1]; i+=2
                continue
            if color not in ("auto","always","ansi","never"):
                eprint(f"error: invalid value '{color}' for '--color <WHEN>'")
                eprint(f"  [possible values: auto, always, ansi, never]")
                eprint("")
                eprint(f"For more information, try '--help'.")
                sys.exit(2)
            i+=1
        elif a in ("-h","--help"):
            long = a=="--help"
            print_help("test", long=long)
            sys.exit(0)
        elif a.startswith("-"):
            eprint(f"error: unexpected argument '{a}' found")
            eprint("")
            eprint(f"  tip: to pass '{a}' as a value, use '-- {a}'")
            eprint("")
            eprint(f"Usage: executable test [OPTIONS]")
            eprint("")
            eprint(f"For more information, try '--help'.")
            sys.exit(2)
        else:
            eprint(f"error: unexpected argument '{a}' found")
            eprint("")
            eprint(f"Usage: executable test [OPTIONS]")
            eprint("")
            eprint(f"For more information, try '--help'.")
            sys.exit(2)
    if skip_snapshot and update_all:
        eprint(f"error: the argument '--skip-snapshot-tests' cannot be used with '--update-all'")
        eprint("")
        eprint(f"Usage: executable test --skip-snapshot-tests --update-all")
        eprint("")
        eprint(f"For more information, try '--help'.")
        sys.exit(2)
    # Need to handle skip+interactive? Not needed
    # Find config
    cfg_path = pathlib.Path(config_file)
    if not cfg_path.exists():
        if pathlib.Path("sgconfig.yml").exists():
