            for res in results_sorted:
                s = res["range"]["byteOffset"]["start"]; e = res["range"]["byteOffset"]["end"]
                text = text[:s] + res["replacement"] + text[e:]
            pathlib.Path(fp).write_text(text, encoding="utf-8")
        if by_file:
            sys.stdout.write(f"Applied {sum(len(v) for v in by_file.values())} changes\\n")
