            # Use lines field
            content = r["lines"]
            # leading spaces already in content?
            # For printing, we need line number: f"{line} │ {content}"
            # And underline: len matched text? But original underline length is length of matched text plus maybe?
            # For rich, they show "│ ^^^^^^^^" where ^ length equals length of matched text (excluding leading spaces?)
            # We'll compute
            # text length
            tlen = len(r["text"])
            # Need leading spaces count for offset?
            # The underline should be under the matched portion, not whole line.
            # For line "    print("hello")" with matched_text "print("hello")" without leading, the underline should be under "print..." not spaces.
            # So we need to compute column of match within line: col is 5 for that? Actually for that case, col 5 (1-indexed) means 4 spaces leading.
            # We'll compute underline: " " * (col-1) + "^"*len(text)
            # But for simplicity, just "^"*len(text) under the line content's indentation?
            # Look at original: for "    print("hello")" they show:
            # 5 │     print("hello")
            #   │     ^^^^^^^^^^^^^^
            # The ^ are under the print, with same leading spaces.
            # So we can produce: f"{' ' * (len(str(line)) + 2)}│ {' ' * (col-1)}{'^'*tlen}"
            # Let's implement.
            sys.stdout.write(f"{sev}[{r['ruleId']}]: {r['message']}\\n")
            sys.stdout.write(f"  ┌─ {r['file']}:{line}:{col}\\n")
            sys.stdout.write(f"  │\\n")
            sys.stdout.write(f"{line} │ {content}\\n")
            # underline
            # Compute prefix spaces: leading spaces before ^ should be same as col-1
            # But content already has leading spaces, we need to align.
            # Original underline row: "  │     ^^^^" where spaces before ^ include leading spaces from content?
            # Actually they show "  │     ^^^^^^^^^^^^^^" where spaces before ^ equals col-1?
            # We'll just do "  │ {' '*(col-1)}{'^'*tlen}"
            sys.stdout.write(f"  │ {' '*(col-1)}{'^'*tlen}\\n")
            if r.get("note"):
                sys.stdout.write(f"  = note: {r['note']}\\n")
            sys.stdout.write("\\n")
        # If no results, no output
        sys.exit(0)
    else:
        # medium/short: print file:line:col: severity[ruleId]: message
        for r in all_results:
            line = r["range"]["start"]["line"]+1
            col = r["range"]["start"]["column"]+1
            sev = r["severity"]
            sys.stdout.write(f"{r['file']}:{line}:{col}: {sev}[{r['ruleId']}]: {r['message']}\\n")
        sys.exit(0)

