            sys.exit(0)
        elif a.startswith("-"):
            eprint(f"error: unexpected argument '{a}' found")
            eprint("")
            eprint(f"  tip: to pass '{a}' as a value, use '-- {a}'")
            eprint("")
            eprint(f"Usage: executable completions [OPTIONS] [SHELL]")
            eprint("")
            eprint(f"For more information, try '--help'.")
            sys.exit(2)
        else:
            if shell is None:
                shell = a
            else:
                eprint(f"error: unexpected argument '{a}' found")
                eprint("")
                eprint(f"Usage: executable completions [OPTIONS] [SHELL]")
                eprint("")
                eprint(f"For more information, try '--help'.")
                sys.exit(2)
            i+=1

    if shell is None:
        # Infer from SHELL env
        shell_env = os.environ.get("SHELL","")
        if "bash" in shell_env:
            shell = "bash"
        elif "zsh" in shell_env:
            shell = "zsh"
        elif "fish" in shell_env:
            shell = "fish"
        elif "powershell" in shell_env or "pwsh" in shell_env:
            shell = "powershell"
        elif "elvish" in shell_env:
            shell = "elvish"
        else:
            eprint("Error: Can not infer which shell to generate completions.")
            eprint("Help: Either specify shell flavor by `sg completions [SHELL]` or set correct `SHELL` environment.")
            eprint("See also: https://ast-grep.github.io/reference/cli.html")
            eprint("")
            sys.exit(1)
    shell = shell.lower()
    if shell not in ("bash","elvish","fish","powershell","zsh"):
        eprint(f"error: invalid value '{shell}' for '[SHELL]'")
        eprint(f"  [possible values: bash, elvish, fish, powershell, zsh]")
        eprint("")
        eprint(f"For more information, try '--help'.")
        sys.exit(2)
    # Output completions from embedded
    if shell in COMPS:
        sys.stdout.write(COMPS[shell])
    else:
        # fallback: try to read from /tmp
        try:
            sys.stdout.write(pathlib.Path(f"/tmp/comp_{shell}.txt").read_text())
        except:
            eprint(f"Error: completions for {shell} not found")
            sys.exit(1)
    sys.exit(0)

