                i+=1
                continue
            k, v = content.split(':', 1)
            k = k.strip()
            v = v.strip()
            if v and ' #' in v:
                v = v.split(' #')[0].strip()
            if parent_type == 'list':
                if parent and isinstance(parent[-1], dict):
                    parent = parent[-1]
                    parent_type = 'dict'
                else:
                    i+=1
                    continue
            if not v:
                peek_idx = i+1
                peek_content = None
                peek_is_list = False
                while peek_idx < len(lines):
                    nxt = lines[peek_idx]
                    if not nxt.strip():
                        peek_idx+=1
                        continue
                    nxt_indent = len(nxt) - len(nxt.lstrip(' '))
                    nxt_content = nxt.strip()
                    if nxt_indent < indent or (nxt_indent == indent and not nxt_content.startswith('- ')):
                        break
                    peek_content = nxt_content
                    peek_is_list = nxt_content.startswith('- ')
                    break
                if peek_is_list:
                    new_list = []
                    parent[k] = new_list
                    stack.append((new_list, indent, k, 'list'))
                else:
                    if peek_content is not None:
                        new_dict = {}
                        parent[k] = new_dict
                        stack.append((new_dict, indent, k, 'dict'))
                    else:
                        parent[k] = None
            else:
                parent[k] = parse_scalar(v)
        i+=1
    return root

def dump_yaml(data, indent=0):
    lines = []
    if isinstance(data, dict):
        for k, v in data.items():
            if isinstance(v, dict):
                if not v:
                    lines.append(' ' * indent + f"{k}: {{}}")
                else:
                    lines.append(' ' * indent + f"{k}:")
                    lines.append(dump_yaml(v, indent+2))
            elif isinstance(v, list):
                if not v:
                    lines.append(' ' * indent + f"{k}: []")
                else:
                    lines.append(' ' * indent + f"{k}:")
                    for item in v:
                        if isinstance(item, dict):
                            sub = dump_yaml(item, indent+2)
                            sub_lines = sub.split('\n')
                            lines.append(' ' * indent + f"- {sub_lines[0].lstrip()}")
                            for sl in sub_lines[1:]:
                                lines.append(sl)
                        elif isinstance(item, str):
                            if ' ' in item or item == '':
                                lines.append(' ' * indent + f"- '{item}'")
                            else:
                                lines.append(' ' * indent + f"- {item}")
                        else:
                            lines.append(' ' * indent + f"- {item}")
            else:
                if isinstance(v, str):
                    if '\n' in v or ':' in v or '#' in v or v == '' or v[0] in ('"', "'"):
                        vq = v.replace("'", "''")
                        lines.append(' ' * indent + f"{k}: '{vq}'")
                    else:
                        lines.append(' ' * indent + f"{k}: {v}")
                elif v is None:
                    lines.append(' ' * indent + f"{k}: null")
                else:
                    lines.append(' ' * indent + f"{k}: {v}")
        return '\n'.join(lines)
    elif isinstance(data, list):
        for item in data:
            if isinstance(item, dict):
                sub = dump_yaml(item, indent+2)
                sub_lines = sub.split('\n')
                lines.append(' ' * indent + f"- {sub_lines[0].lstrip()}")
                for sl in sub_lines[1:]:
                    lines.append(sl)
            else:
                lines.append(' ' * indent + f"- {item}")
        return '\n'.join(lines)
    else:
        return str(data)
